"""Unit 35: Tagalog Basic Course, Semester I, Chapter 11, Lesson 1: Simple Directions.
Original lessons; the scope follows the DLIFLC Tagalog Basic Course (piloting edition, June 2017).
Pictures, maps, audio, partner work and role plays are left out; the book's answer keys are used (misprints noted),
numbers, addresses and times are written in words in the spoken lines."""
from dsl_tl import *

_V = "aeiou"


def dd(xs, ans, n=3, extra=()):
    out = []
    for x in list(xs) + list(extra):
        if x != ans and x not in out:
            out.append(x)
    return out[:n]


def P(rows):
    return [(t, e) for _, t, e in rows]


def um_forms(root):
    if root[0] in _V:
        return f"um{root}", f"um{root}", f"uma{root}", f"a{root}"
    i = next(k for k, ch in enumerate(root) if ch in _V)
    c, rest, v = root[:i], root[i:], root[i]
    return f"{c}um{rest}", f"{c}um{rest}", f"{c}um{v}{root}", f"{c}{v}{root}"


