_UMROWS = [[um_forms(r)[0], um_forms(r)[1], um_forms(r)[2], um_forms(r)[3]] for r in _ROOTS]
_DIRS = [("east", "silangan"), ("west", "kanluran"), ("north", "hilaga"), ("south", "timog"), ("left", "kaliwa"), ("right", "kanan"), ("middle, center", "gitna")]


def _pa(w):
    return "pa" + w


def _paum(w):
    return "p" + "um" + "a" + w


_DIRROWS = [[e, t, _pa(t), _paum(t), "patungong " + t] for e, t in _DIRS]
_PAEX = [("Papunta na ako diyan.", "I’ll be going there now, or I’m on my way there now."), ("Pababa na ako ng bahay.", "I’m going down now from the house."), ("Mag-drive kang pahilaga.", "Drive going to the north."), ("Paakyat ang daan diyan.", "The road there is going up.")]
_PAUM = [("Pumasilangan ka ng mga dalawang milya.", "Go towards the east for about two miles."), ("Tapos pumatimog ka ng sampung milya.", "Then go towards the south for ten miles."), ("Pumakanluran ka.", "Go towards the west."), ("Pumakanan ka ng mga singkuwenta piye.", "Go right for about fifty feet."), ("Mag-drive kang patungong hilaga.", "Drive towards the north.")]
_CJ = [("Maglalakad na lang ako at baka mahuli na ako.", "I will just walk because I might be late. (at as “because”)"), ("Pumarada ka na lang diyan at maglakad ka na lang.", "Just park there and walk. (at as “and”)"), ("Puwede pero medyo malayo.", "You can, but it’s a bit far."), ("Sumakay ka sa MRT pero mag-ingat ka.", "Ride the MRT but be careful."), ("Puwede kang pumasilangan pero delikado diyan.", "You can go east but it’s dangerous there."), ("Pagkatapos makikita po ninyo ang unang ilaw trapiko.", "Then you will see the first traffic light."), ("Pagkatapos kumanan sa ilalim ng unang tulay.", "Afterwards turn right under the first bridge."), ("Bawal kasi ang mag-u-turn kaya lumiko ka sa kanan saka mag-u-turn ulit.", "Because it is forbidden to make a U-turn, turn right and then make a U-turn again."), ("Wala kasing sariling parking ang resto.", "Because the restaurant does not have its own parking.")]
L4 = lesson(
    "C11 L1 · Um verbs for directions, pa/pa+um/patungo and the conjunctions at, pero, pagkatapos, kasi",
    "Kumanan ka · Pumasilangan ka · Pahilaga, pumahilaga, patungong hilaga · At, pero, pagkatapos, kasi",
    requires=[],
    cards=[
        card("A. Um verbs for giving directions and instructions", "One use of um verbs is giving directions and instructions. Three things are instructive. (1) The infinitive form of the verb is used. (2) Unlike in English, “you” (ka, kayo) is not optional in ordinary speech or writing; only in printed directions and military commands is the word omitted. (3) “You” comes right after the verb, except in the presence of a few words such as lang (“just”) when used with the plural kayo (as in Dumiretso lang po kayo).", examples=passage(_EXU)),
        card("The um verbs in the presentations", "Identify the um verbs in these sentences and translate them. The um verbs are dumiretso, kumaliwa, kunin, lumabas, kumanan, lumiko, kumanan, kumaliwa and pumarada. (Where the book writes lumakad or limakad in the last line, the lesson writes maglakad, which is the form the dialog used; both mean “walk.”)", examples=passage(_UMS)),
        card("Additional um verbs: past, present, future", "Practice conjugating these verbs. The past and the infinitive share the same form (the um goes after the first consonant); the present repeats the first syllable after the um; the future repeats the first syllable of the root. Verbs whose root begins with a vowel start with um: umabante, umaabante, aabante.", tables=[table(["Infinitive and past", "Present (is doing)", "Future (will do)"], [[r[0], r[2], r[3]] for r in _UMROWS], say=[]), table(["Root", "Infinitive", "Present", "Future"], [[_ROOTS[i]] + _UMROWS[i][1:] for i in range(len(_ROOTS))], say=[])]),
        card("B. Pa, pa+um and patungo with direction words", "To express “go in the direction of” or “in the manner of” use pa, pa+um or patungo with direction words. With pa: papunta (going to), pababa (going down), pahilaga (going north), paakyat (going up). You can add pa to other direction words: pasilangan (going east), pakanluran (going west), patimog (going south). To form pa+um simply add um after the letter p: pa + um = pumasilangan. Patungo means “going in the direction of”; with a direction word it takes the linker ng: patungong hilaga.", examples=passage(_PAEX + _PAUM)),
        card("The direction words with pa, pa+um and patungo", "", tables=[table(["English", "Direction word", "With pa", "With pa+um", "With patungo + ng"], _DIRROWS, say=[])]),
        card("Practice", "As a class, give a command or direction to the classmate on your right, using ka or kayo as appropriate; the class judges whether the task was done correctly (a classroom activity, left out)."),
        card("C. The conjunctions at, pero, pagkatapos and kasi", "Conjunctions (pangatnig in Tagalog) connect words, phrases or whole clauses. At can mean “and” or “because.” Pero means “but”; it is a Spanish cognate; subali’t, nguni’t and datapwa’t mean the same but are used in higher-level discourse or formal prose. Pagkatapos means “after,” “afterwards” or “then.” Kasi means “because.”", examples=passage(_CJ)),
    ],
    exercises=uniq(
        tr_q(_EXU) + rev_q(_EXU) + tr_q(_UMS) + rev_q(_UMS) + tr_q(_PAEX) + rev_q(_PAEX) + tr_q(_PAUM) + rev_q(_PAUM) + tr_q(_CJ) + rev_q(_CJ)
        + [M(f"What is the present form of {r}?", um_forms(r)[2], dd([um_forms(x)[2] for x in _ROOTS], um_forms(r)[2]), f"{um_forms(r)[0]}, {um_forms(r)[2]}, {um_forms(r)[3]}.") for r in _ROOTS]
        + [M(f"What is the future form of {r}?", um_forms(r)[3], dd([um_forms(x)[3] for x in _ROOTS], um_forms(r)[3]), f"{um_forms(r)[0]}, {um_forms(r)[2]}, {um_forms(r)[3]}.") for r in _ROOTS]
        + [M(f"What is the infinitive (and past) form of the root {r}?", um_forms(r)[0], dd([um_forms(x)[0] for x in _ROOTS], um_forms(r)[0]), um_forms(r)[0] + ".") for r in _ROOTS]
        + [M(f"What is the pa+um form of {t} ({e})?", _paum(t), dd([_paum(x[1]) for x in _DIRS], _paum(t)), _paum(t) + ".") for e, t in _DIRS]
        + [M(f"What is the patungo form of {t} ({e})?", "patungong " + t, dd(["patungong " + x[1] for x in _DIRS], "patungong " + t), "patungong " + t + ".") for e, t in _DIRS]
        + [M("Which form of the verb is used in giving directions?", "the infinitive", ["the past", "the future", "the present"], "infinitive."), M("When is ka or kayo omitted?", "in printed directions and military commands", ["never", "always", "only in questions"], "omitted."), M("What does the conjunction pero mean?", "but", ["and", "because", "then"], "pero."), M("What does pagkatapos mean?", "after, afterwards, then", ["because", "but", "or"], "pagkatapos."), M("What does kasi mean?", "because", ["but", "then", "and"], "kasi."), M("What can at mean?", "and or because", ["only but", "only then", "only if"], "at."), M("Which conjunction is used in formal prose for but?", "subali’t", ["pero", "kasi", "pagkatapos"], "subali’t."), M("What does patungo mean?", "go in the direction of", ["going down", "going up", "turn around"], "patungo."), M("Which linker goes between patungo and a direction word?", "ng", ["na", "sa", "ay"], "patungong.")]
        + [F("___ ka sa unang daan. (Make a right.)", "Kumanan", ["Kumaliwa", "Lumabas"], "kumanan."), F("Tumawag po kayo ng ___. (doctor)", "doktor", ["bangko", "hotel"], "doktor."), F("Mag-drive kang ___ hilaga. (towards the; with the linker)", "patungong", ["pahilagang", "pumahilaga"], "patungong hilaga."), F("Puwede ___ medyo malayo. (but)", "pero", ["kasi", "pagkatapos"], "pero."), F("Bawal ___ ang mag-u-turn. (because)", "kasi", ["pero", "pagkatapos"], "kasi."), F("Maglalakad na lang ako ___ baka mahuli na ako. (because)", "at", ["pero", "o"], "at as because.")]
    ),
)

