_S11 = [("Soldier", "Magandang araw po. Paano po ba makakarating sa bahay ng mananahi?", "Good day. How can I get to the seamstress’s house?"), ("Neighbor", "Madali lang. Sumakay ka ng dyip papuntang Barangay Bato-Bato, San Isidro. Bumaba ka sa gasolinahan sa tapat ng palengke. May maliit na kalye sa kaliwa ng gasolinahan.", "It’s easy. Take a jeepney bound for Barangay Bato-Bato, San Isidro. Get off at the gasoline station across from the market. There is a small street to the left of the gasoline station."), ("Soldier", "Ano po ang pangalan ng kalye?", "What is the name of the street?"), ("Neighbor", "Hindi ko alam.", "I don’t know."), ("Soldier", "Baka po maligaw ako.", "I’m afraid I might get lost."), ("Neighbor", "Hindi! Sundan mo lang ang kalye hanggang makita mo ang malaking puno ng mangga. Kumanan ka at makikita mo ang maliit na karinderya. Katabi nito ang bahay ni Aling Iska.", "No! Just follow the street until you see a big mango tree. Turn right and you will see a small eating place. Next to it is Aling Iska’s house."), ("Soldier", "Maraming salamat po.", "Thank you very much."), ("Neighbor", "Walang anuman.", "You’re welcome.")]
