        + [M("Which jeepney does the neighbor tell the soldier to take?", "one for Barangay Bato-Bato, San Isidro", ["one for Manila", "one for Narra market", "one for Puerto Princesa"], "Bato-Bato."), M("Where does the soldier get off?", "at the gasoline station across the market", ["at the church", "at the mango tree", "at the bakery"], "gasolinahan."), M("What landmark comes after following the street?", "a big mango tree", ["a bridge", "a church", "a school"], "puno ng mangga."), M("What is next to the karinderya?", "Aling Iska’s house", ["the tailor’s shop", "the market", "a school"], "katabi."), M("What does the customer ask the clerk for in the role play?", "landmarks and street names", ["a menu", "the price", "a taxi"], "palatandaan."), M("What else does the customer do?", "make a reservation", ["order food", "complain", "cancel"], "magpareserba."), M("What does Hindi ko alam mean?", "I don’t know", ["I know", "I forgot", "I’m lost"], "hindi ko alam."), M("What does Baka po maligaw ako mean?", "I might get lost", ["I will arrive", "I am tired", "I am lost already"], "maligaw."), M("What does patungong silangan mean?", "heading east", ["heading west", "heading up", "heading home"], "patungong silangan."), M("What does Bawal ang pumarada diyan mean?", "parking there is prohibited", ["parking there is free", "park there", "do not walk"], "bawal."), M("What does Huminto ka sa stop sign mean?", "stop at the stop sign", ["go through the stop sign", "turn at the stop sign", "park at the stop sign"], "huminto."), M("What does Umatras ka pa ng mga dalawang metro mean?", "back up about two more meters", ["go forward two meters", "turn right", "stop"], "umatras.")]
